import { describe, it, expect, beforeEach } from 'vitest';
import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { Watchlist } from '../app/watchlist/watchlist';
import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

function mk(id: number): TmdbMovie {
  return { id, title: `Movie ${id}`, release_date: '2020-01-01', poster_path: null, overview: '' };
}

describe('Watchlist component', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('toggleWatched flips the watched state in the store and movies shows unwatched first', async () => {
    const store = new WatchlistStore();
    store.add(mk(1));
    store.add(mk(2));
    TestBed.configureTestingModule({
      imports: [Watchlist],
      providers: [provideRouter([]), { provide: WatchlistStore, useValue: store }],
    });
    const fixture = TestBed.createComponent(Watchlist);
    await fixture.whenStable();

    fixture.componentInstance.toggleWatched(1);
    expect(store.items().find((m) => m.id === 1)?.watched).toBe(true);

    fixture.componentInstance.toggleWatched(1);
    expect(store.items().find((m) => m.id === 1)?.watched).toBe(false);

    fixture.componentInstance.toggleWatched(1);
    expect(fixture.componentInstance.movies().map((m) => m.id)).toEqual([2, 1]);
  });
});
